"""Taxes Made Simple and Insurance Basics for FinLearn (ages 18-23, India, rupees).

Educational, not tax or insurance advice. Tax figures follow the new regime as of FY 2026-27 and are checked in
backend/tests/check_life_math.py. Rules change every year: lessons tell learners to confirm current figures.
"""
from seed_data import _id, _intro, _teach, _example, _flash, _mcq, _concept
from seed_finance import _choice, _outcome

LIFE_SEED_VERSION = "life-1"


# ---------------------------------------------------------------------------
# TAXES MADE SIMPLE
# ---------------------------------------------------------------------------

def _tax_chapter(course_id):
    ch_id = _id()
    ch = {"id": ch_id, "course_id": course_id, "order": 1, "title": "Your first tax return",
          "description": "How income tax really works, which regime to pick, how to file, and how investments are taxed."}
    m_id = _id()
    m = {"id": m_id, "chapter_id": ch_id, "order": 1, "title": "Income tax for beginners"}

    c1 = _concept(m_id, 1,
        "How income tax works",
        "Explain slabs, the standard deduction, the rebate and why tax is charged on slices of income.",
        "Income tax is not one rate on all your income. Your income is cut into slices, and each slice has its own rate. "
        "Only the part of your income that falls in a higher slice is taxed at the higher rate.",
        "Neha earns ₹10,00,000 a year. After the ₹75,000 standard deduction her taxable income is ₹9,25,000, and the rebate brings her tax to zero.",
        ["Tax is charged slice by slice, so a raise never reduces your take-home pay.",
         "The new regime has a nil slab up to ₹4 lakh, then 5%, 10%, 15%, 20%, 25% and 30% as income rises.",
         "Salaried people get a ₹75,000 standard deduction automatically.",
         "A rebate makes tax zero if taxable income is up to ₹12 lakh (about ₹12.75 lakh salary).",
         "Rules change every Budget, so check the current figures before you file."],
        ["Thinking a higher slab taxes ALL your income at that rate.",
         "Refusing a raise or bonus because it 'pushes you into a higher bracket'.",
         "Forgetting the 4% cess that is added on top of the tax."],
        [
            _intro("Does a raise cost you money?", "A friend says, 'I turned down a raise so I would not pay more tax.' Sounds clever. It is actually a myth, and by the end of this lesson you will see why."),
            _teach("Tax comes in slices",
                   "Think of your income as a ladder with steps. The first ₹4 lakh is taxed at 0%. The next ₹4 lakh (up to ₹8 lakh) is taxed at 5%. The next ₹4 lakh (up to ₹12 lakh) at 10%, then 15% up to ₹16 lakh, 20% up to ₹20 lakh, 25% up to ₹24 lakh, and 30% above that. These are the new-regime slabs for FY 2026-27. Each step charges its own rate only on the money inside it. At the end, 4% health and education cess is added to the tax.",
                   ["₹0 to 4 lakh: nil", "₹4 to 8 lakh: 5%", "₹8 to 12 lakh: 10%", "₹12 to 16 lakh: 15%, then 20%, 25%, 30% above ₹24 lakh", "Cess: 4% of the tax"]),
            _example("A salary of ₹15 lakh",
                     "Rohan earns ₹15,00,000. The standard deduction of ₹75,000 leaves ₹14,25,000 taxable. Slice by slice: nothing on the first ₹4 lakh, 5% of ₹4 lakh is ₹20,000, 10% of ₹4 lakh is ₹40,000, and 15% of the last ₹2,25,000 is ₹33,750. That adds up to ₹93,750, plus 4% cess of ₹3,750, so ₹97,500 in all.",
                     "Only the last ₹2,25,000 was taxed at 15%. The rest was taxed at lower rates."),
            _flash("What is the standard deduction?", "A flat amount (₹75,000 in the new regime) that salaried people can subtract from salary before tax, with no bills needed."),
            _choice("Meera earns ₹16,00,000 a year and her manager offers a ₹1,00,000 raise. A colleague says, 'Careful, you will jump into a higher tax bracket and take home less than now.'",
                    "What is true?",
                    [("She would take home less than before, so she should refuse", "bad",
                      "Tax is charged slice by slice. Only the extra rupees fall into the higher slice, so pay after tax can only go up with a raise. It never goes down."),
                     ("Only the extra ₹1,00,000 meets the higher rate, so she keeps most of it", "good",
                      "Right. Her first ₹16 lakh is taxed as before. The raise adds only about ₹16,900 of tax (including cess), so she keeps about ₹83,000 of it. A raise is almost always worth taking.",
                      _outcome(("Extra pay", 100000), ("Extra tax with cess", 16900), "She keeps about ₹83,100 of the extra ₹1,00,000.")),
                     ("Taxes only apply to bonuses, not to a raise", "bad", "Salary raises are income and are taxed like any salary. The point is that the extra income is taxed at the slice it falls in.")]),
            _teach("The rebate and the zero-tax zone",
                   "There is a tax rebate (called Section 87A) of up to ₹60,000 in the new regime. If your taxable income is ₹12 lakh or less, the rebate cancels your whole tax. Add the ₹75,000 standard deduction and a salaried person with a ₹12,75,000 salary pays no income tax. Just above that limit, 'marginal relief' makes sure you never pay more tax than the income you earned above ₹12 lakh. The rebate does not cancel tax on special-rate income such as share gains.",
                   ["Taxable income up to ₹12 lakh: tax is nil", "Salary up to about ₹12.75 lakh: zero tax", "Marginal relief softens the cliff just above the limit"]),
            _choice("Neha earns ₹10,00,000 a year from her first job. She is nervous that tax will take a big chunk.",
                    "How much income tax does she actually pay in the new regime?",
                    [("About ₹1,00,000, since 10% of her salary goes to tax", "bad",
                      "Tax is not a flat share of salary. Her taxable income is ₹9,25,000 after the standard deduction, and the rebate brings tax to zero."),
                     ("Nothing. Her taxable income is ₹9,25,000, which is under ₹12 lakh, so the rebate cancels the tax", "good",
                      "Right. Before the rebate she would owe ₹32,500 (₹20,000 + ₹12,500), but the ₹60,000 rebate covers it fully. Employers may still deduct TDS monthly, which she can claim back when she files.",
                      _outcome(("Tax before rebate", 32500), ("Tax after rebate", 0), "The rebate cancels all of it.")),
                     ("Exactly ₹32,500, because the rebate only applies to older people", "bad", "The rebate is for everyone with taxable income up to ₹12 lakh, whatever the age.")]),
            _mcq("In India's slab system, what does the higher rate apply to?", ["Only the income that falls in that higher slice", "All of your income", "Only your bonus", "Only your savings"], 0,
                 "Each slice is taxed at its own rate. Only rupees that fall inside a higher slice meet the higher rate."),
            _mcq("A salaried person's taxable income is ₹8,00,000 after deductions. Using the slabs, what is the tax before rebate and cess?", ["₹20,000", "₹40,000", "₹80,000", "Nil"], 0,
                 "Nothing on the first ₹4 lakh, then 5% of the next ₹4 lakh = ₹20,000. (With the rebate, the final tax is nil.)"),
        ], xp=25)

    c2 = _concept(m_id, 2,
        "Old regime or new regime?",
        "Compare the two regimes and pick the one that leaves more money in your pocket.",
        "India has two ways to calculate tax. The new regime has lower rates but few deductions and is the default. "
        "The old regime has higher rates but lets you subtract things like 80C investments and HRA. You pick whichever costs less.",
        "On a ₹10 lakh salary, the old regime with full deductions still costs ₹75,400 in tax, while the new regime costs nothing.",
        ["The new regime is the default unless you choose the old one.",
         "Old regime deductions include Section 80C (up to ₹1.5 lakh), HRA, home loan interest and 80D health premiums.",
         "At lower and middle incomes the new regime usually wins unless you have large deductions.",
         "Never buy a product just to save tax. Compare the two regimes with real numbers first.",
         "Salaried people can switch every year, with the employer or when filing."],
        ["Locking money into a long-term product only to claim 80C.",
         "Comparing the regimes without counting the standard deduction in each.",
         "Choosing by what a relative did instead of calculating."],
        [
            _intro("Two roads, one destination", "Both regimes lead to a tax number. The skill is to work out which road is shorter for you. Spoiler: for most young earners it is the new one."),
            _teach("What each regime offers",
                   "New regime: low rates, a ₹75,000 standard deduction, and the ₹60,000 rebate up to ₹12 lakh taxable income, but almost no other deductions. Old regime: higher rates (nil to ₹2.5 lakh, 5% to ₹5 lakh, 20% to ₹10 lakh, 30% above), a ₹50,000 standard deduction, and a long list of deductions such as 80C (EPF, PPF, ELSS, life insurance, up to ₹1.5 lakh), HRA, home loan interest and 80D health insurance. The old regime's rebate covers income only up to ₹5 lakh.",
                   ["New: lower rates, simple, no proofs", "Old: higher rates, needs deductions and proofs", "You can compare both every year"]),
            _example("Same salary, two answers",
                     "Aman earns ₹10,00,000. In the old regime he claims the ₹50,000 standard deduction and ₹1,50,000 under 80C, leaving ₹8,00,000 taxable. Tax: ₹12,500 on the slice to ₹5 lakh, plus 20% of ₹3 lakh = ₹60,000, so ₹72,500, plus ₹2,900 cess = ₹75,400. In the new regime his taxable income is ₹9,25,000 and the rebate makes tax nil.",
                     "Even with the full ₹1.5 lakh under 80C, the old regime cost him ₹75,400 more."),
            _flash("Which regime is the default?", "The new regime. You only get the old one if you choose it."),
            _choice("Sana earns ₹9,00,000. An agent says, 'Put ₹1,50,000 into a 15-year savings scheme right now to save tax under 80C, or you will lose the benefit!'",
                    "What should Sana do first?",
                    [("Buy it immediately so she does not lose the tax saving", "bad",
                      "Rushing creates a bad trade. Her taxable income is ₹8,25,000 in the new regime, which is already under ₹12 lakh, so her tax is nil. Locking money for years to save tax she would not pay is a poor deal."),
                     ("Calculate tax in both regimes. In the new regime her tax is nil, so the investment would save her nothing", "good",
                      "Right. Compare first, decide second. A product should be bought because you want it, not because of a deadline."),
                     ("Ask a friend which regime they chose and copy it", "ok", "Friends may have very different incomes and deductions. Calculate with your own numbers.")]),
            _teach("When the old regime can still win",
                   "The old regime can come out ahead if your deductions are large: for example high rent with HRA, a home loan with big interest, and plenty of 80C and 80D claims. As your income grows past about ₹15 lakh and you have a home loan, it is worth running both numbers. For a first-job salary with few deductions the new regime is usually simpler and cheaper.",
                   ["Big HRA + home loan interest + 80C + 80D can tip it", "Run both numbers every year", "Do not buy products only to cut tax"]),
            _choice("Kabir's employer asks him to choose a tax regime in April. He has no home loan, pays ₹12,000 rent on a ₹14 lakh salary, and has only a small insurance policy.",
                    "How should he decide?",
                    [("Choose the old regime because it has more deductions", "bad",
                      "More deductions only help if you actually have them. With few claims, the old regime's higher rates usually cost more."),
                     ("Add up his real deductions, calculate tax in both, and pick the lower number", "good",
                      "Right. It takes ten minutes with a tax calculator, and the choice can be changed every year.")]),
            _mcq("Which of these is mainly an OLD-regime deduction?", ["Section 80C investments up to ₹1.5 lakh", "The ₹75,000 standard deduction", "A zero-tax slab to ₹4 lakh", "The 4% cess"], 0,
                 "80C is a classic old-regime deduction. The ₹75,000 standard deduction and the ₹4 lakh nil slab belong to the new regime."),
            _mcq("When should you buy an investment only to save tax?", ["Only if you wanted it anyway and the numbers work", "Always, before 31 March", "Never think about it", "Whenever an agent calls"], 0,
                 "Tax saving is a side benefit. A product you do not need, with a lock-in you cannot afford, is a bad deal even if it cuts tax."),
        ], xp=25)

    c3 = _concept(m_id, 3,
        "Filing your first tax return",
        "Understand TDS, Form 16, AIS and the steps to file and verify an income tax return.",
        "A tax return (ITR) is a yearly form where you report your income and tax paid. Your employer or bank may already have deducted tax (TDS) for you. "
        "Filing matches what they deducted with what you actually owe, and gives you a refund if they took too much.",
        "Zoya's employer deducted ₹18,000 of TDS during the year. Her real tax is nil, so she files a return and claims the full ₹18,000 back as a refund.",
        ["TDS means tax deducted at source: tax cut before you receive the money.",
         "Form 16 is your employer's summary of salary and TDS.",
         "AIS (Annual Information Statement) lists income reported about you. Check it before filing.",
         "The usual due date for salaried people is 31 July. Check it each year.",
         "After filing, e-verify the return (for example with Aadhaar OTP) or it does not count."],
        ["Missing the due date: it can cost a late fee and delay refunds.",
         "Not checking AIS and missing interest or dividend income.",
         "Filing but forgetting to e-verify."],
        [
            _intro("Is filing for you?", "You earn less than the taxable limit, so why file a return at all? Because it can bring your money back, and it is proof of income for loans and visas."),
            _teach("TDS, Form 16 and your PAN",
                   "When your employer pays your salary, they may deduct an estimated tax (TDS) every month and deposit it with the government in your PAN's name. Banks also deduct TDS on large FD interest. After the year ends you get Form 16 from your employer showing salary and tax deducted. All of this appears in your Form 26AS and the Annual Information Statement (AIS) on the income tax website. Your PAN must be linked with Aadhaar.",
                   ["TDS is tax already paid for you", "Form 16 comes from your employer", "AIS and Form 26AS show what is reported under your PAN", "PAN must be linked to Aadhaar"]),
            _example("The refund Zoya almost missed",
                     "Zoya earns ₹7,50,000 and her employer deducts ₹1,500 a month as TDS, ₹18,000 in the year, by mistake. Her taxable income is ₹6,75,000, which is under the ₹12 lakh limit, so her tax is nil. She files her return, and within a few weeks the ₹18,000 is credited to her bank account.",
                     "Without filing, the government keeps the extra TDS."),
            _flash("What does TDS stand for?", "Tax deducted at source. It is tax taken before you receive your pay or interest."),
            _choice("Arnav's total income for the year is ₹3,00,000 from freelance design work, which is below the taxable limit. The company that paid him deducted 10% TDS, ₹30,000, before paying.",
                    "Should he file a return?",
                    [("No, since his income is below the limit nothing is required", "bad",
                      "He may not be forced to file, but without a return the ₹30,000 deducted as TDS stays with the government. Filing is how he claims it back."),
                     ("Yes. His tax is nil, so filing lets him claim the full ₹30,000 back, and the return becomes proof of income", "good",
                      "Right. Filing is free if you do it yourself, brings the TDS back as a refund, and creates a record that banks and embassies like to see."),
                     ("He should wait three years to see whether the tax office contacts him", "bad", "Waiting only risks missing the refund and the due dates. File on time.")]),
            _teach("The steps, in order",
                   "1) Collect Form 16, bank interest certificates and your AIS. 2) Log in to the income tax e-filing website with your PAN. 3) Choose the right form (ITR-1 for most simple salaried returns). 4) Check that income and TDS match the AIS. 5) Choose your regime. 6) Submit, then e-verify within 30 days. If you skip e-verification the return is treated as not filed. Rules and due dates are updated every year, so read the instructions on the official site.",
                   ["Collect Form 16 and AIS", "Match TDS and income", "Pick the regime", "Submit and e-verify"]),
            _choice("Isha filed her return on 28 July but did not e-verify it. Three months later she wonders why her refund has not arrived.",
                    "What is the most likely reason?",
                    [("Refunds always take a year", "bad", "Refunds usually arrive within weeks of a verified return."),
                     ("The return was never e-verified, so it was not processed. She needs to check the status and fix it", "good",
                      "Right. An unverified return is treated as not filed. Always finish e-verification, usually in minutes, using Aadhaar OTP or net banking."),
                     ("The tax office forgot her", "bad", "It is much more likely that a step was missed on her side.")]),
            _mcq("What is Form 16?", ["Your employer's summary of salary and TDS", "A loan application", "A bank passbook", "A PAN card"], 0,
                 "Form 16 comes from your employer and summarises your salary and the tax they deducted."),
            _mcq("After submitting a return, what must you do?", ["E-verify it", "Print it and post it to the bank", "Delete the account", "Nothing"], 0,
                 "A return that is not e-verified is treated as not filed. Verify it with Aadhaar OTP, net banking or another approved method."),
        ], xp=25)

    c4 = _concept(m_id, 4,
        "Tax on investments and side income",
        "Know how FD interest, share gains, crypto and freelance income are taxed in simple terms.",
        "Different money is taxed differently. Interest from a bank FD is added to your income. Gains from shares and crypto have special rates. "
        "Side income, such as freelancing or tuition, is added to your total income.",
        "Riya sells shares she held for 2 years and makes ₹1,75,000. Only the part above ₹1,25,000 is taxed at 12.5%, so she pays about ₹6,500 including cess.",
        ["FD and savings interest is taxed at your slab rate. Banks may deduct TDS.",
         "Equity shares and equity mutual funds: gains within 12 months are taxed at 20%, and gains after 12 months at 12.5% above ₹1.25 lakh a year.",
         "Crypto gains are taxed at a flat 30%, losses cannot be set off against other gains, and there is a 1% TDS on transfers.",
         "Freelance and side income is added to your total income. Keep records.",
         "These rates were current when this course was written. Check the latest before you act."],
        ["Forgetting to report FD interest or small share gains.",
         "Thinking crypto gains are 'not taxed' because the exchange does not file for you.",
         "Mixing personal and side-income money so you cannot tell what you earned."],
        [
            _intro("Is it all taxed the same?", "You earn ₹20,000 from FD interest, ₹20,000 from selling shares and ₹20,000 from a design gig. Three kinds of income, three kinds of tax rules."),
            _teach("Interest and side income",
                   "Interest from savings accounts and FDs is added to your total income and taxed at your slab. If your interest from one bank goes above ₹50,000 in a year, the bank deducts 10% TDS (limits are higher for seniors). Freelance or tuition income is also added to your total income, and you need to keep records of what you earned. Even if you are under the limit, report it when you file.",
                   ["Interest is taxed at your slab rate", "TDS on FD interest above ₹50,000 a year at one bank", "Side income is added to total income", "Keep records and bank statements"]),
            _teach("Shares, mutual funds and crypto",
                   "For equity shares and equity mutual funds, selling within 12 months gives a short-term gain, taxed at 20%. Selling after 12 months gives a long-term gain, where the first ₹1.25 lakh of gains in a year is tax free and the rest is taxed at 12.5%. Crypto and other digital assets are taxed at a flat 30% on gains, with no deduction except the purchase cost, no offset of losses against other gains, and a 1% TDS on transfers above certain limits.",
                   ["Shares held under 12 months: 20%", "Shares held over 12 months: 12.5% on gains above ₹1.25 lakh a year", "Crypto: flat 30%, no loss offset, 1% TDS"]),
            _example("Two sales, two taxes",
                     "Riya sells shares she held for 2 years and makes a ₹1,75,000 gain. The first ₹1,25,000 is tax free, so ₹50,000 is taxed at 12.5%, which is ₹6,250, plus 4% cess of ₹250, so ₹6,500. Separately she sells other shares after 5 months for a ₹40,000 gain, taxed at 20%, which is ₹8,000, plus cess ₹320, so ₹8,320.",
                     "How long you hold matters: holding past a year lowered the rate from 20% to 12.5% and added a ₹1.25 lakh tax-free allowance."),
            _flash("Share gains held over a year are called...", "Long-term capital gains. The first ₹1.25 lakh a year is tax free and the rest is taxed at 12.5%."),
            _choice("Dev bought a coin for ₹50,000 and sold it for ₹70,000. A friend says, 'Crypto is not regulated, so it is not taxed.'",
                    "What is the correct picture?",
                    [("Not taxed, because exchanges do not report it", "bad",
                      "Crypto gains are taxable at a flat 30%, and exchanges report transfers. Ignoring it can lead to penalties."),
                     ("Taxed at 30% on the ₹20,000 gain, which is ₹6,000 plus cess", "good",
                      "Right. 30% of ₹20,000 is ₹6,000, plus 4% cess of ₹240, so ₹6,240. He should also know that a loss on another coin cannot reduce this tax.",
                      _outcome(("Gain", 20000), ("Tax with cess", 6240), "About 31% of the gain goes to tax.")),
                     ("Taxed as salary at his slab rate", "bad", "Crypto has its own flat rate. It is not charged at your slab rate.")]),
            _choice("Pooja earns ₹4,000 a month tutoring students on the side and does not log it anywhere. At filing time she cannot remember how much she earned.",
                    "What is the smartest habit?",
                    [("Estimate and hope for the best", "bad", "A guess can be too low or too high, and it is hard to defend if you are asked."),
                     ("Keep a simple monthly record of what she earns, such as in a notes app, and match it to her bank credits", "good",
                      "Right. A basic monthly log takes a minute and makes filing easy. My money in this app can help you keep it.")]),
            _mcq("You sell equity shares after holding them for 18 months and make a gain of ₹1,00,000 in the year. What is the tax?", ["Nil, because the gain is under the ₹1.25 lakh limit", "12.5% of ₹1,00,000", "20% of ₹1,00,000", "30% of ₹1,00,000"], 0,
                 "Long-term gains up to ₹1.25 lakh in a year are tax free. A gain of ₹1,00,000 is within that allowance."),
            _mcq("Which statement about crypto tax is correct?", ["Gains are taxed at a flat 30%", "Crypto is not taxed", "Gains are taxed at 5%", "Only exchanges pay tax"], 0,
                 "Digital asset gains face a flat 30% tax, with no offset for losses, and a 1% TDS on transfers above limits."),
        ], xp=25)

    m["concepts"] = [c1, c2, c3, c4]
    ch["modules"] = [m]
    return ch


# ---------------------------------------------------------------------------
# INSURANCE BASICS
# ---------------------------------------------------------------------------

def _insurance_chapter(course_id):
    ch_id = _id()
    ch = {"id": ch_id, "course_id": course_id, "order": 1, "title": "Insurance that actually protects you",
          "description": "Health, term life and vehicle cover in plain words, and how to avoid being sold the wrong thing."}
    m_id = _id()
    m = {"id": m_id, "chapter_id": ch_id, "order": 1, "title": "Insurance essentials"}

    c1 = _concept(m_id, 1,
        "Health insurance",
        "Explain sum insured, premium, waiting periods, room-rent limits and why employer cover is not enough.",
        "Health insurance pays hospital bills so one illness does not wipe out your savings. You pay a small yearly premium. "
        "If you are hospitalised, the insurer pays up to your sum insured.",
        "Karan needs a 3-day hospital stay costing ₹1,80,000. Because he has a ₹10 lakh health cover, he pays almost nothing through a cashless claim.",
        ["Premium is what you pay each year. Sum insured is the most the insurer will pay in a year.",
         "Pre-existing illnesses have a waiting period (the legal maximum is now 3 years).",
         "After 5 continuous years the insurer cannot reject a claim except for fraud (the moratorium).",
         "Room-rent limits can shrink your whole claim. Choose a policy without a tight cap.",
         "Employer cover ends when you leave the job, so a personal policy is important."],
        ["Hiding a medical condition on the form.",
         "Relying only on employer cover.",
         "Choosing a cover that is too small, such as ₹2 lakh, for city hospitals."],
        [
            _intro("One bill, years of savings", "A week in a private hospital can cost ₹2 to 5 lakh. For many families that is two or three years of savings gone. Health insurance exists for exactly this moment."),
            _teach("The words you will see",
                   "Premium: what you pay each year to keep the policy. Sum insured: the highest amount the insurer pays in a year. Cashless: the hospital bills the insurer directly at a network hospital. Reimbursement: you pay first and claim back. Co-pay: a share of every claim you pay yourself. Waiting period: a time after buying when some illnesses are not covered. Since 2024 the maximum waiting period for pre-existing conditions is 3 years, and the moratorium (after which claims cannot be disputed except for fraud) is 5 continuous years.",
                   ["Premium = yearly price", "Sum insured = yearly limit", "Cashless vs reimbursement", "Co-pay and waiting periods reduce what you get"]),
            _example("The room-rent trap",
                     "Meera's policy allows a room up to ₹3,000 a day. She is admitted to a room costing ₹6,000 a day and the bill totals ₹2,00,000. Because her room costs twice her limit, the insurer applies 'proportionate deduction' and pays only about half, ₹1,00,000, of the whole bill, including doctor and procedure fees. She pays ₹1,00,000 herself.",
                     "A room-rent cap can cut the entire claim, not just the room cost."),
            _flash("What is a 'waiting period'?", "A period after you buy the policy when certain illnesses are not covered yet."),
            _choice("Aman, 24, has a health policy from his employer with ₹5 lakh cover. He is planning to switch jobs next month.",
                    "What is the wise move?",
                    [("Nothing, because he will get a new employer policy soon", "bad",
                      "There may be a gap between jobs, and a new employer policy can restart waiting periods. A personal policy follows you."),
                     ("Buy his own policy now, while he is young and healthy, and keep the employer cover as extra", "good",
                      "Right. Premiums are lower when you are young, and a personal policy keeps your waiting periods running no matter where you work.")]),
            _teach("Choosing a policy",
                   "Look at: sum insured (₹5 to 10 lakh is a common start in cities, with a cheap 'super top-up' to add more), network hospitals near you, room-rent limit (prefer no cap or a single private room), co-pay (prefer none), waiting periods, and the restore benefit that refills your cover after a claim. Be honest about your health on the form: hiding a condition can get a future claim rejected.",
                   ["Pick enough cover, with a top-up if needed", "Avoid tight room-rent caps and co-pay", "Check network hospitals near you", "Answer the health form truthfully"]),
            _choice("Nisha fills in her health proposal form. She has mild asthma but thinks mentioning it will raise her premium.",
                    "What should she do?",
                    [("Leave it out to keep the premium low", "bad",
                      "If the insurer later finds out, they can reject a claim, and the lower premium costs far more. Always disclose."),
                     ("Disclose it. The insurer may add a waiting period or a small loading, but the cover stays valid", "good",
                      "Right. Honest disclosure protects the claim. The small extra cost is worth the safety.")]),
            _mcq("What does a 'cashless claim' mean?", ["The hospital bills the insurer directly at a network hospital", "You do not pay a premium", "Cash is never used in hospitals", "The policy has no limit"], 0,
                 "Cashless means the hospital settles with the insurer directly. You pay only items the policy does not cover."),
            _mcq("Why is relying only on employer health cover risky?", ["It ends when you leave the job", "It is always too expensive", "It never covers surgery", "It needs a deposit"], 0,
                 "Employer cover stops when employment ends, and a new policy may start new waiting periods."),
        ], xp=25)

    c2 = _concept(m_id, 2,
        "Term life insurance",
        "Explain who needs term insurance, how much cover to buy and why it is the simplest kind.",
        "Term insurance pays a lump sum to your family if you die during the policy. It pays nothing if you live, which is why it is so cheap. "
        "You need it only if someone depends on your income.",
        "At 25, a non-smoker may pay roughly ₹10,000 a year for ₹1 crore of cover, much less than a savings-type policy would charge.",
        ["Term insurance is pure protection with no maturity payout.",
         "You need life cover only if people or loans depend on your income.",
         "A common rule is cover of 10 to 15 times your yearly income.",
         "Buying younger means a lower premium that stays fixed for the whole term.",
         "Always tell the insurer the truth about health, smoking and income."],
        ["Buying a savings plan because 'term gives nothing back'.",
         "Choosing too little cover, such as ₹10 lakh.",
         "Skipping the nominee or giving wrong details."],
        [
            _intro("Do you need it yet?", "At 21 with no one depending on you, the honest answer may be 'not yet'. But you will, one day, and the price goes up every year you wait."),
            _teach("How term insurance works",
                   "You pick a cover amount (for example ₹1 crore), a term (for example until age 60) and pay a fixed premium every year. If you die during the term, your nominee receives the cover. If you outlive the term, you get nothing back, like car insurance you did not need to claim. That is why it costs a fraction of savings-linked policies. The premium is set by your age, health, smoking status and the cover chosen.",
                   ["Cover amount + term + yearly premium", "Pays the nominee if you die during the term", "No payout if you outlive the term", "Cheaper when you are young and healthy"]),
            _example("Who truly needs it?",
                     "Rohan, 22, is single with no loans and parents who earn their own income. He does not need life cover right now. His cousin Priya, 28, supports her parents, and her father co-signed her ₹20 lakh education loan. If she died, they would struggle. She buys ₹1 crore of term cover.",
                     "Buy term insurance when others rely on your income or share your debt, not just because it is popular."),
            _flash("What does term insurance pay if you outlive the policy?", "Nothing. It is pure protection, which is why the premium is low."),
            _choice("Aarav, 27, earns ₹8 lakh a year and supports his younger sister's studies. He is choosing how much term cover to buy.",
                    "About how much cover fits the common rule of 10 to 15 times income?",
                    [("₹10 lakh", "bad", "That is barely more than a year of income. It would not last his sister through her studies."),
                     ("₹80 lakh to ₹1.2 crore", "good", "Right. 10 to 15 times ₹8 lakh is ₹80 lakh to ₹1.2 crore, enough to replace his income and cover loans for years. It is a rule of thumb you can adjust for loans and dependants."),
                     ("₹1,000", "bad", "That is a joke amount. Cover should replace the income your family would lose.")]),
            _teach("Good habits",
                   "Compare a few insurers on claim settlement ratio and complaint records, and buy online if you can, as it is cheaper. Declare smoking, health and income honestly. Name a nominee and tell your family where the papers are. Pay on time, because a lapsed policy means no cover. Avoid add-ons you do not need. Check the policy within the 15-day free look period, and return it if you are unhappy.",
                   ["Compare insurers and claim records", "Be honest about health and smoking", "Name a nominee and tell your family", "Use the 15-day free look period"]),
            _choice("Zara, 24, smokes occasionally. She wants a lower premium on her term plan and the form asks, 'Do you smoke or use tobacco?'",
                    "What is the right answer?",
                    [("'No', because she smokes only a little", "bad",
                      "If the insurer finds out later, they can reject the claim, and her family would be left with nothing."),
                     ("'Yes', and accept the higher premium", "good", "Right. Telling the truth keeps the claim safe. The extra premium is the price of a promise that is actually worth something.")]),
            _mcq("Who most needs term life insurance?", ["A person whose family depends on their income", "A single student with no dependants", "A pet owner", "Anyone who wants guaranteed returns"], 0,
                 "Term cover protects the people who depend on your income. If nobody does, you can wait."),
            _mcq("Why is term insurance cheaper than savings-type policies?", ["It pays only if you die during the term and has no maturity benefit", "It covers fewer people", "It is run by the government", "It has hidden charges"], 0,
                 "Term insurance is pure protection with no savings part, so the premium is far lower for the same cover."),
        ], xp=25)

    c3 = _concept(m_id, 3,
        "Bike and car insurance",
        "Explain third-party versus comprehensive cover, IDV and no-claim bonus.",
        "Motor insurance is required by law for every vehicle on the road. Third-party cover pays for harm you cause to others. "
        "Comprehensive cover also pays for damage to your own vehicle.",
        "Dev rides into a parked car and dents it. His third-party policy pays the car owner, but only a comprehensive policy would repair his own bike.",
        ["Third-party insurance is mandatory in India.",
         "Third-party cover does not pay for damage to your own vehicle.",
         "Comprehensive cover adds own-damage protection, theft and some natural calamities.",
         "IDV (insured declared value) is the most you would get if the vehicle is stolen or written off, and it falls as the vehicle ages.",
         "A no-claim bonus (NCB) lowers your premium for each claim-free year."],
        ["Driving with an expired policy.",
         "Setting IDV too low to save a little premium.",
         "Making tiny claims and losing the no-claim bonus."],
        [
            _intro("Your first bike", "You just bought your first bike. The dealer says, 'Insurance is included.' What exactly is included, and is it enough?"),
            _teach("Two main types",
                   "Third-party cover is the legal minimum. It pays for injury or damage you cause to other people and their property, but nothing for your own vehicle. Comprehensive cover includes third-party plus own damage from accidents, theft, fire and some natural events. Personal accident cover for the owner-driver is usually included. Driving without valid insurance is illegal and can bring a fine.",
                   ["Third-party: mandatory, covers others only", "Comprehensive: covers others and your vehicle", "Policy must stay valid at all times"]),
            _example("A small dent, a big decision",
                     "Priya's scooter gets a ₹2,000 scratch. If she claims it on her comprehensive policy, she may lose her no-claim bonus, which could raise her next premium by more than ₹2,000 over the coming years. She decides to pay for this small repair herself and keeps the bonus for bigger events.",
                     "Claim for serious damage and theft, and pay tiny repairs from your own pocket."),
            _flash("What does IDV stand for?", "Insured declared value: the most you can get if the vehicle is stolen or damaged beyond repair."),
            _choice("Kunal buys a second-hand bike. The seller says, 'Just keep third-party cover, it is cheaper and legal.' The bike is worth ₹60,000 and he cannot afford a ₹60,000 loss.",
                    "What is the better choice?",
                    [("Third-party only: it is legal, so it is fine", "ok",
                      "It meets the law, but any damage or theft of his own bike comes entirely from his pocket. For a bike he cannot afford to lose, that is a risk."),
                     ("Comprehensive cover, so his own bike is protected too", "good",
                      "Right. The extra premium protects a ₹60,000 asset. Compare quotes and set a fair IDV."),
                     ("No insurance, since it is an old bike", "bad", "Driving without a valid policy is illegal and can mean fines and full liability if you hurt someone.")]),
            _teach("Renewal and the no-claim bonus",
                   "Renew before the policy expires. A lapse can mean losing the no-claim bonus, a vehicle inspection, and no cover if something happens during the gap. The no-claim bonus grows with each claim-free year, up to 50% off your own-damage premium, and it belongs to you, not the vehicle, so you can carry it to a new vehicle.",
                   ["Renew on time", "NCB grows each claim-free year", "NCB stays with you when you change vehicles"]),
            _choice("Maya's bike policy expired two weeks ago. She plans to ride only to the shop nearby, 'just this once'.",
                    "What is the risk?",
                    [("None, it is a short ride", "bad",
                      "An accident takes one second. Without a valid policy she may pay all costs herself and could be fined."),
                     ("She should renew first, even if a short inspection is needed, before riding again", "good",
                      "Right. An expired policy means no cover and possible fines. Renewing late can also cost her the no-claim bonus.")]),
            _mcq("What does third-party insurance NOT cover?", ["Damage to your own vehicle", "Injury to another person", "Damage to someone else's car", "Legal liability for harm you caused"], 0,
                 "Third-party covers others. Damage to your own vehicle needs comprehensive or own-damage cover."),
            _mcq("What is a no-claim bonus?", ["A discount on your premium for each claim-free year", "A bonus paid by the dealer", "A tax refund", "A free service coupon"], 0,
                 "NCB rewards claim-free years with a lower premium, and it stays with you if you change vehicles."),
        ], xp=25)

    c4 = _concept(m_id, 4,
        "Insurance is not an investment",
        "Spot mis-selling and know why term cover plus a separate investment usually works better.",
        "Insurance is meant to protect you from loss, not to grow your money. Many policies mix the two and do neither job well. "
        "Keep protection and investing separate.",
        "A policy asks for ₹50,000 a year for 20 years and promises a lump sum later. The same money split into ₹10,000 of term cover and ₹40,000 a year in an index fund could grow far more.",
        ["Term insurance protects. Investments grow. Do not mix them.",
         "Policies that promise returns and insurance together often give a low return and small cover.",
         "A pushy seller, a 'limited-time offer' or a promise of guaranteed returns are red flags.",
         "You have a free look period of at least 15 days to cancel a policy and get a refund (less small charges).",
         "Insurance products should be bought because you understand them."],
        ["Buying insurance as a tax-saving or savings product.",
         "Signing papers you have not read.",
         "Believing the bank 'manager' who sells you a policy while you open an account."],
        [
            _intro("The friendly bank visit", "You go to a bank to open an account. A smiling person says, 'Great news! This plan gives you cover and returns, safe and tax free.' It sounds too good. It often is."),
            _teach("Why mixing is a problem",
                   "Savings-type policies, such as endowment and money-back plans and many unit-linked plans, charge you for insurance, sales commission and management in one package. The cover is often small, and the return is often low, sometimes close to what a safe deposit pays. Separating the jobs is simple: buy a term plan for protection and put the rest into investments you understand, such as an index fund SIP. Each does its own job at lower cost.",
                   ["Protection: term insurance", "Growth: separate investments", "Mixed policies often give small cover and modest returns"]),
            _example("₹50,000 a year, two ways",
                     "Plan A: a savings-type policy costing ₹50,000 a year for 20 years with a life cover of only ₹5 lakh. Plan B: ₹10,000 a year for ₹1 crore of term cover, and ₹40,000 a year invested in an index fund. Assume the fund grows 10% a year, which is not guaranteed. After 20 years, ₹40,000 a year would have grown to about ₹22.9 lakh, and the family had ₹1 crore of cover the whole time.",
                     "Plan B costs the same, protects 20 times more, and has room to grow. The 10% is an assumption, not a promise."),
            _flash("How long is the 'free look' period?", "At least 15 days after you receive the policy. You can cancel and get your premium back, less small charges."),
            _choice("A salesperson at a bank says: 'This plan guarantees returns, gives tax benefits and covers your life. Sign today. The offer ends tomorrow.'",
                    "What should you do?",
                    [("Sign today so you do not miss the offer", "bad",
                      "Urgency is a sales tactic. A good product will still be there next week. Never sign something you do not understand."),
                     ("Ask for the policy document, check the actual cover, the premium, the lock-in and the returns, and compare with term insurance plus an SIP", "good",
                      "Right. Take the papers home, read the charges and the surrender terms, and compare. If it still looks good, nothing is lost by waiting.")]),
            _teach("Red flags and your rights",
                   "Warning signs: the seller pushes a deadline, promises 'guaranteed' or 'double your money', calls it a 'deposit' or 'investment' when it is insurance, refuses to show the policy document, or will not say how much you get if you stop paying early. If you do buy, check the policy within the free look period and cancel if it is not what was promised. You can complain to the insurer, then to the IRDAI grievance system or the insurance ombudsman.",
                   ["Deadlines and 'guaranteed' are red flags", "Check the policy within the free look period", "Escalate complaints to IRDAI or the ombudsman"]),
            _choice("Rhea realises, two days after buying a savings-type policy, that the cover is only ₹3 lakh and that she cannot take the money out for 10 years.",
                    "What can she do?",
                    [("Nothing. Once signed, it is final", "bad", "The free look period lets her cancel within at least 15 days and get her premium back, less small charges."),
                     ("Use the free look period to cancel and get her premium back, then look at term insurance and an index fund", "good",
                      "Right. The free look period exists for exactly this. She can now choose with full information.")]),
            _mcq("What is the better split for most people?", ["Term insurance for cover and a separate investment for growth", "One policy that does both", "Only an FD", "No cover and no savings"], 0,
                 "Separate products are usually cheaper and clearer: term insurance protects, investments grow."),
            _mcq("Which sentence from a seller is a red flag?", ["'Sign today, the offer ends tomorrow and returns are guaranteed.'", "'Take the papers home and read them.'", "'Here is the policy document.'", "'You have a 15-day free look period.'"], 0,
                 "Pressure and guaranteed returns are classic warning signs. A trustworthy seller lets you read first."),
        ], xp=25)

    m["concepts"] = [c1, c2, c3, c4]
    ch["modules"] = [m]
    return ch


